  ('c28', 'حلول الموبايل السريع', 'إصلاح آيفون وسامسونج وقطع غيار', 'إصلاح شاشات وبطاريات ومنافذ شحن وصيانة سوفتوير.', 4.7, 98, 1.8, 'شارع ركب', 'رام الله والبيرة', true, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=400&q=80&fit=crop', '+970590000028', 'فحص', 'مجاني', true, 'آيفون سامسونج شاشة بطارية شاحن سوفتوير', 'خدمة سريعة في نفس اليوم', ARRAY['tech']::text[], 31.9079, 35.2051, 8, true, '09:00 ص - 10:00 م'),
  ('c29', 'سباكة الطيبة', 'مضخات مياه وسخانات وتمديدات', 'تركيب وصيانة سخانات المياه والمضخات وشبكات المياه.', 4.9, 87, 3.7, 'البيرة القديمة', 'رام الله والبيرة', true, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400&q=80&fit=crop', '+970590000029', 'كشفية', '25 ₪', true, 'سباكة سخان مضخة مياه تمديدات تسريب', 'متابعة بعد الخدمة وضمان على بعض الإصلاحات', ARRAY['plumbing']::text[], 31.9189, 35.2241, 15, true, '07:00 ص - 10:00 م'),
