INSERT INTO public.craftsman_services (id, craftsman_id, title, description, duration, price_range, price_note, icon, is_active)
VALUES
  ('s1', 'c1', 'صيانة غسالات أوتوماتيك متقدمة', 'معالجة مشاكل عصر الملابس، تهريب المياه، صيانة أو برمجة البورد الإلكتروني.', '45 - 90 دقيقة', '₪120 - ₪250', 'حسب العطل والقطع', 'washer', true),
  ('s2', 'c1', 'صيانة نشافات وجلايات صحون', 'تبديل هيترات التسخين، حساسات الحرارة، مضخات التصريف، وفلاتر الأمان.', '60 دقيقة', '₪100 - ₪180', 'استرشادي', 'dishes', true),
  ('s3', 'c1', 'فحص محركات وتغيير رولمان بلي (Bearing)', 'حل مشكلة الصوت العالي والاهتزاز أثناء التنشيف بمعدات سحب ألمانية وهيدروليكية.', 'ضمان 6 شهور على القطع', '₪180 - ₪320', 'شامل الصوف والبولنج', 'settings', true),
  ('s4', 'c1', 'كشف منزلي ومعاينة فنية فورية', 'زيارة ميدانية شاملة فحص حقيقي بالجهاز الإلكتروني داخل رام الله والبيرة وبيتونيا.', 'تخصم من قيمة التصليح عند التنفيذ', '₪50', 'كشفية استرشادية', 'toolbox', true),
  ('s5', 'c2', 'تركيب وتمديد إنارة ذكية للشقق', 'تركيب سبوتات لايت، ليد مخفي، وأنظمة تحكم ذكية بالهاتف.', 'ساعتان إلى 4 ساعات', '₪150 - ₪350', 'حسب المساحة ونقاط الكهرباء', 'toolbox', true),
  ('s6', 'c3', 'غسيل وصيانة تكييف دورية', 'تنظيف فلاتر، تعبئة غاز الفريون الأصلي، وفحص تسريب المياه والكمبروسر.', '45 دقيقة لكل وحدة', '₪70 - ₪120', 'خصم عند وجود أكثر من مكيف', 'toolbox', true)
INSERT INTO public.reviews (id, craftsman_id, author_name, author_initial, rating, service, comment, tags, helpful, time_ago, verified_request)
VALUES
  ('c1-r1', 'c1', 'أحمد البرغوثي', 'أ', 5.0, 'صيانة غسالة LG', 'الغسالة كانت بتعمل صوت قوي وما بتعصر. فحصها بسرعة وحدد المشكلة وركّب القطعة بنفس الزيارة، والتكلفة كانت واضحة من البداية.', ARRAY['إتقان العمل', 'سريع وملتزم']::text[], 18, 'منذ يومين', true),
  ('c1-r2', 'c1', 'أم تامر', 'ت', 5.0, 'إصلاح جلاية صحون', 'ملتزم بالموعد وتعامل محترم جدًا. حل مشكلة التسريب بدون ما يضطرنا نشتري جهاز جديد.', ARRAY['دقيق في الموعد', 'أمين ومحترم']::text[], 11, 'منذ أسبوع', true),
  ('c1-r3', 'c1', 'طارق ناصر الدين', 'ط', 4.5, 'تبديل مضخة غسالة', 'شغل ممتاز وقطع الغيار كانت واضحة مع ضمان. تأخر قليلًا بسبب الطريق لكنه تواصل معنا قبل الموعد.', ARRAY['قطع أصلية', 'تواصل ممتاز']::text[], 20, 'منذ أسبوعين', true),
  ('c1-r4', 'c1', 'ليان حمدان', 'ل', 5.0, 'كشف وصيانة منزلية', 'الكشف كان مرتب والمشكلة توضحت لنا قبل الإصلاح. أعطانا خيارات بدل ما يفرض حل واحد.', ARRAY['شفافية', 'سعر منصف']::text[], 9, 'منذ 3 أسابيع', true),
  ('c2-r1', 'c2', 'ليلى من الطيرة', 'ل', 5.0, 'تركيب إنارة ذكية', 'ركبوا الإنارة في الشقة بسرعة والشغل طلع مرتب جدًا، خصوصًا توزيع الأسلاك وإنهاء المفاتيح.', ARRAY['شغل نظيف', 'سريع وملتزم']::text[], 14, 'منذ شهر', true),
  ('c3-r1', 'c3', 'سامر خليل', 'س', 4.8, 'صيانة مكيف سبليت', 'المكيف صار يبرد ممتاز بعد غسيل الوحدة وتعبئة الغاز، تعامل راقي وأسعار مناسبة.', ARRAY['دقة في الموعد', 'خبرة ممتازة']::text[], 16, 'منذ شهر', true)
